# Content for the link pages. Plain HTML fragments; no brand names, no person names.
def ul(items, cls="ticks"):
    return '<ul class="%s">' % cls + "".join("<li>%s</li>" % i for i in items) + "</ul>"
def ol(items):
    return '<ol class="steps">' + "".join("<li><h3>%s</h3><p>%s</p></li>" % i for i in items) + "</ol>"
def p(*t):
    return "".join("<p>%s</p>" % x for x in t)

